<script lang="ts">
 import UnsavedChanges from '$lib/shared/presentation/ui/UnsavedChanges.svelte';
 import {fieldValidation} from '$lib/shared/presentation/form-validation';
 import TeamAvatar from './TeamAvatar.svelte';
 import AvatarEditor from '$lib/features/identity/presentation/AvatarEditor.svelte';
 import type {AvatarGateway} from '$lib/features/identity/application/avatars';
 import {onMount} from 'svelte';
 import {page} from '$app/stores';
 import type {TeamsGateway} from '../application/teams';
 import {requestTeam} from '../application/teams';
 import {canManage,type Team,type Member,type Invitation} from '../domain/team';
 import type {Account} from '$lib/features/identity/domain/account';
 import SectionHeading from '$lib/shared/presentation/ui/SectionHeading.svelte';
 import RequestStatus from '$lib/features/publishing/presentation/RequestStatus.svelte';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureCode,noticeText} from '$lib/shared/presentation/copy';
 let {user,gateway,avatars}:{user:Account|null;gateway:TeamsGateway;avatars?:AvatarGateway}=$props();const {locale}=useLocale();
 let teams=$state<Team[]>([]),selected=$state(''),members=$state<Member[]>([]),moreTeams=$state(false),moreMembers=$state(false),teamOffset=0,memberOffset=0,loading=$state(true),busy=$state(false),error=$state(''),notice=$state('');
 let invitations=$state<Invitation[]>([]),moreInvitations=$state(false),invitationOffset=0;
 let form=$state<'new'|'edit'|null>(null),name=$state(''),slug=$state(''),description=$state(''),telegramURL=$state(''),email=$state(''),role=$state<'member'|'editor'>('member'),removeID=$state('');
 let guard=$state<{confirmDiscard():boolean}>();
 let baseline=$state(''),avatarVersion=$state(0),membersLoaded=$state(false),invitationsLoaded=$state(false);
 const profileValue=$derived(JSON.stringify([name,slug,description,telegramURL]));
 const dirty=$derived((form!==null&&profileValue!==baseline)||email.trim()!=='');
 function closeForm(){if(guard&&!guard.confirmDiscard())return;form=null;}
 function changeTeam(event:Event){const control=event.currentTarget as HTMLSelectElement;if(guard&&!guard.confirmDiscard()){control.value=selected;return;}selected=control.value;form=null;email='';void run(()=>loadMembers());}
 const active=$derived(teams.find(team=>team.id===selected));
 const roles=$derived({owner:text($locale,'Иесі','Владелец'),editor:text($locale,'Редактор','Редактор'),member:text($locale,'Қатысушы','Участник')});
 function open(mode:'new'|'edit'){if(guard&&!guard.confirmDiscard())return;form=mode;error='';notice='';name=mode==='edit'?active?.name||'':'';slug=mode==='edit'?active?.slug||'':'team-'+crypto.randomUUID().slice(0,8);description=mode==='edit'?active?.description||'':'';telegramURL=mode==='edit'?active?.telegramURL||'':'';baseline=JSON.stringify([name,slug,description,telegramURL]);}
 async function load(append=false){const batch=await gateway.list(append?teamOffset:0);teamOffset=(append?teamOffset:0)+batch.length;moreTeams=batch.length===100;teams=append?[...teams,...batch.filter(team=>!teams.some(old=>old.id===team.id))]:batch;if(!selected&&teams.length)selected=teams[0].id;if(!append)await loadMembers();}
 async function loadMembers(append=false){const current=active;if(!append){members=[];invitations=[];membersLoaded=false;invitationsLoaded=false;memberOffset=0;moreMembers=false;moreInvitations=false;removeID='';}if(!current||!canManage(current))return;const batch=await gateway.members(current.id,append?memberOffset:0);if(selected!==current.id)return;memberOffset=(append?memberOffset:0)+batch.length;moreMembers=batch.length===100;members=append?[...members,...batch]:batch;membersLoaded=true;if(!append)await loadInvitations();}
 async function loadInvitations(append=false){const current=active;if(!current||!canManage(current))return;const batch=await gateway.invitations(current.id,append?invitationOffset:0);if(selected!==current.id)return;invitationOffset=(append?invitationOffset:0)+batch.length;moreInvitations=batch.length===100;invitations=append?[...invitations,...batch.filter(item=>!invitations.some(old=>old.id===item.id))]:batch;invitationsLoaded=true;}
 async function sendInvitation(recipient:string,invitationRole:'member'|'editor'){await gateway.invite(active!.id,recipient,invitationRole);await loadInvitations();notice=text($locale,'Шақыру поштаға жіберілді. Алдыңғы сілтеме енді жарамсыз.','Приглашение отправлено на почту. Предыдущая ссылка больше не действует.');}
 async function run(action:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await action();}catch(failure){error=failureCode(failure);}finally{busy=false;}}
 onMount(()=>{if(!user){loading=false;return;}void(async()=>{try{await load();if(!teams.length||$page.url.searchParams.has('new'))open('new');}catch(failure){error=failureCode(failure);}finally{loading=false;}})();});
 async function save(event:SubmitEvent){event.preventDefault();await run(async()=>{if(form==='edit'&&active){await gateway.update(active.id,{name,slug,description,telegramURL});await load();notice=text($locale,'Өзгерістер сақталды.','Изменения сохранены.');}else{const team=await requestTeam(gateway,{name,slug,description,telegramURL});teams=[team,...teams];selected=team.id;await loadMembers();notice=text($locale,'Команда өтінімі жіберілді. Мақұлдауды осы жерден бақыла.','Заявка команды отправлена. Здесь появится решение.');}form=null;});}
</script>
<UnsavedChanges {dirty} bind:this={guard}/>
<svelte:head><title>{text($locale,'Командаларым','Мои команды')} — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>

<SectionHeading level={1} title={text($locale,'Командалар','Команды')} description={!teams.length?text($locale,'Командаға өтінім бер немесе шақыруды қабылда.','Подай заявку на команду или прими приглашение.'):undefined}>{#snippet actions()}{#if user&&form!=='new'}<button class="button primary" onclick={()=>open('new')}>{text($locale,'Команда құру','Создать команду')}</button>{/if}{/snippet}</SectionHeading>
 {#if teams.length>1||moreTeams}<label class="team-select">{text($locale,'Команда','Команда')}<select value={selected} disabled={busy} onchange={changeTeam}>{#each teams as team}<option value={team.id}>{team.name}</option>{/each}</select></label>{/if}
{#if !teams.length&&!loading}<details class="solo-tip"><summary>{text($locale,'Жалғыз аударасың ба?','Переводишь один?')}</summary><p class="muted">{text($locale,'Бір адамнан тұратын команда құрып, өз атыңмен жариялауға болады.','Создай команду из одного человека и публикуй под своим именем.')}</p></details>{/if}
{#if !user}<div class="empty-state"><h2>{text($locale,'Алдымен аккаунтқа кір','Войди в аккаунт')}</h2><p>{text($locale,'Командаға өтінім аккаунтыңа байланысады.','Заявка команды будет связана с твоим аккаунтом.')}</p><a class="button primary" href="/login?returnTo=%2Fstudio%2Fteams">{text($locale,'Кіру','Войти')}</a></div>
{:else}
 {#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{/if}{#if notice}<p class="form-message success" role="status">{notice}</p>{/if}
 {#if !user.verified}<div class="form-message"><strong>{text($locale,'Алдымен поштаңды раста','Сначала подтверди почту')}</strong><p>{text($locale,'Осыдан кейін командаға өтінім жібере аласың.','После этого сможешь отправить заявку команды.')}</p><a class="button subtle" href="/settings">{text($locale,'Растау хатын жіберу','Отправить письмо подтверждения')}</a></div>{/if}
 {#if loading}<p role="status">{text($locale,'Командалар жүктелуде…','Загружаем команды…')}</p>{:else}
 {#if form}<section class="team-form"><div class="form-heading"><h2>{form==='new'?text($locale,'Жаңа командаға өтінім','Заявка на новую команду'):text($locale,'Команда деректері','Данные команды')}</h2><button type="button" class="button subtle" disabled={busy} onclick={closeForm}>{text($locale,'Жабу','Закрыть')}</button></div><form use:fieldValidation={{locale:$locale}} onsubmit={save}>
  <label>{text($locale,'Команда атауы','Название команды')}<input bind:value={name} required minlength="2" maxlength="80" placeholder={text($locale,'Мысалы, Дала тобы','Например, Дала тобы')}/></label>
  <label>{text($locale,'Команда туралы','О команде')}<textarea bind:value={description} maxlength="2000" rows="4" placeholder={text($locale,'Не аударасыңдар, кім қатысады, қандай тәжірибе бар?','Что переводите, кто участвует, какой есть опыт?')}></textarea></label>
  <label>{text($locale,'Ашық Telegram сілтемесі · міндетті емес','Публичная ссылка Telegram · необязательно')}<input type="url" bind:value={telegramURL} maxlength="128" placeholder="https://t.me/dala_team" pattern={'https://t\\.me/[A-Za-z][A-Za-z0-9_]{4,31}/?'}/><small>{text($locale,'Команданың ашық бетінде көрінеді.','Будет видна на публичной странице команды.')}</small></label>
  <details><summary>{text($locale,'Команда сілтемесі','Адрес команды')}</summary><label>{text($locale,'Сілтемедегі атау','Название в ссылке')}<input bind:value={slug} required pattern="[a-z0-9]+(-[a-z0-9]+)*" minlength="3" maxlength="64" autocomplete="off"/></label><p class="muted">/teams/{slug}</p></details>
  {#if form==='new'}<p class="muted">{text($locale,'Сен команда иесі боласың. Әкімші мақұлдағаннан кейін жобалар сұрай аласың.','Ты станешь владельцем команды. После одобрения администратором сможешь запрашивать проекты.')}</p>{/if}
  <button class="button primary" disabled={busy||!user.verified}>{busy?text($locale,'Сақталуда…','Сохраняем…'):form==='new'?text($locale,'Өтінімді жіберу','Отправить заявку'):active?.reviewStatus==='rejected'?text($locale,'Қайта қарауға жіберу','Отправить на повторное рассмотрение'):text($locale,'Сақтау','Сохранить')}</button>
 </form></section>{/if}

 {#if moreTeams}<button class="button subtle" disabled={busy} onclick={()=>run(()=>load(true))}>{text($locale,'Тағы командалар','Ещё команды')}</button>{/if}
 {#if active}<section class="team"><div class="team-heading"><div class="team-identity"><TeamAvatar id={active.id} name={active.name} size={88} version={avatarVersion}/><div><h2>{active.name}</h2><p class="muted">{active.role?roles[active.role]:''}</p></div></div><RequestStatus status={active.approved?'approved':active.reviewStatus||'pending'}/></div>{#if active.description}<p class="description">{active.description}</p>{/if}{#if active.telegramURL}<p class="team-contact"><span>Telegram</span><a class="auth-link" href={active.telegramURL} target="_blank" rel="noreferrer">{active.telegramURL} ↗</a></p>{/if}
  {#if !active.approved}<div class="review-note"><h3>{active.reviewStatus==='rejected'?text($locale,'Өтінімді түзету керек','Заявку нужно исправить'):text($locale,'Өтінім қаралуда','Заявка на рассмотрении')}</h3><p>{active.reviewNote||text($locale,'Әкімші команданы тексереді. Мақұлданған соң жобаларға өтінім беруге болады.','Администратор проверит команду. После одобрения можно подавать заявки на проекты.')}</p><div class="actions"><button class="button subtle" disabled={busy} onclick={()=>run(()=>load())}>{text($locale,'Күйін жаңарту','Обновить статус')}</button>{#if canManage(active)}<button class="button subtle" onclick={()=>open('edit')}>{active.reviewStatus==='rejected'?text($locale,'Өтінімді түзету','Исправить заявку'):text($locale,'Деректерді өңдеу','Изменить данные')}</button>{/if}</div></div>
  {:else}<div class="actions"><a class="button subtle" href={'/teams/'+encodeURIComponent(active.slug)}>{text($locale,'Ашық парақша','Публичная страница')}</a><a class="button primary" href={'/studio/projects?team='+active.id}>{text($locale,'Команда жобалары','Проекты команды')}</a>{#if active.role==='owner'||active.role==='editor'}<a class="button subtle" href={'/studio/requests?new=1&team='+encodeURIComponent(active.id)}>{text($locale,'Жоба сұрау','Запросить проект')}</a>{/if}{#if canManage(active)}<button class="button subtle" onclick={()=>open('edit')}>{text($locale,'Команданы өңдеу','Изменить команду')}</button>{/if}</div>{/if}
  {#if avatars&&(active.role==='owner'||active.role==='editor')}<details class="avatar-settings"><summary>{text($locale,'Команда аватары','Аватар команды')}</summary>{#key user.id+':'+active.id}<AvatarEditor gateway={avatars} kind="team" actorId={user.id} ownerId={active.id} name={active.name} onsaved={()=>avatarVersion=Date.now()}/>{/key}</details>{/if}
  {#if canManage(active)}<details class="management" open><summary>{text($locale,'Қатысушылар','Участники')} <span class="count">{membersLoaded?members.length:'—'}{moreMembers?'+':''}</span></summary>
   <div class="member-list">{#each members as member}<div class="member-row"><div><strong>{member.email}</strong><small>{roles[member.role]}</small></div>{#if member.role!=='owner'}<button class="button subtle" disabled={busy} onclick={()=>removeID=member.userId}>{text($locale,'Шығару','Удалить из команды')}</button>{/if}</div>{#if removeID===member.userId}<div class="review-note"><p>{text($locale,'Қатысушы команда жобаларына кіре алмайды. Қайтару үшін жаңа шақыру керек.','Участник потеряет доступ к проектам команды. Для возвращения понадобится новое приглашение.')}</p><div class="actions"><button class="button primary" disabled={busy} onclick={()=>run(async()=>{await gateway.remove(active!.id,member.userId);await loadMembers();})}>{text($locale,'Шығаруды растау','Подтвердить удаление')}</button><button class="button subtle" onclick={()=>removeID=''}>{text($locale,'Бас тарту','Отмена')}</button></div></div>{/if}{/each}</div>
   {#if moreMembers}<button class="button subtle" disabled={busy} onclick={()=>run(()=>loadMembers(true))}>{text($locale,'Тағы қатысушылар','Ещё участники')}</button>{/if}
   <details class="invitations"><summary>{text($locale,'Шақырулар','Приглашения')} <span class="count">{invitationsLoaded?invitations.length:'—'}{moreInvitations?'+':''}</span></summary>
   <button class="button subtle" disabled={busy} onclick={()=>run(()=>loadInvitations())}>{text($locale,'Шақыруларды жаңарту','Обновить приглашения')}</button>
   <div class="invitation-list">{#each invitations as invitation (invitation.id)}<div class="member-row"><div><strong>{invitation.email}</strong><small>{roles[invitation.role]} · {invitation.status==='pending'?text($locale,'Жауап күтілуде','Ожидает ответа'):invitation.status==='expired'?text($locale,'Мерзімі аяқталды','Истекло'):text($locale,'Күші жойылды','Отозвано')}</small><small>{text($locale,'Жарамдылық мерзімі: ','Срок действия: ')}{new Date(invitation.expiresAt).toLocaleDateString($locale==='ru'?'ru-RU':'kk-KZ')}</small></div><div class="actions"><button class="button subtle" disabled={busy||!user.verified} onclick={()=>run(()=>sendInvitation(invitation.email,invitation.role))}>{text($locale,'Қайта жіберу','Отправить снова')}</button>{#if invitation.status!=='revoked'}<button class="button subtle" disabled={busy} onclick={()=>run(async()=>{await gateway.revokeInvitation(active!.id,invitation.id);await loadInvitations();})}>{text($locale,'Шақыруды қайтарып алу','Отозвать приглашение')}</button>{/if}</div></div>{:else}<p class="muted">{text($locale,'Қабылданбаған шақырулар жоқ.','Непринятых приглашений нет.')}</p>{/each}</div>
   {#if moreInvitations}<button class="button subtle" disabled={busy} onclick={()=>run(()=>loadInvitations(true))}>{text($locale,'Тағы шақырулар','Ещё приглашения')}</button>{/if}</details>
   <details class="invite-composer"><summary>{text($locale,'Қатысушы шақыру','Пригласить участника')}</summary><form use:fieldValidation={{locale:$locale}} onsubmit={event=>{event.preventDefault();void run(async()=>{await sendInvitation(email,role);email='';});}}><label>{text($locale,'Пошта','Почта')}<input type="email" bind:value={email} required autocomplete="off"/></label><label>{text($locale,'Рөл','Роль')}<select bind:value={role}><option value="member">{text($locale,'Қатысушы — файл жүктейді','Участник — загружает файлы')}</option><option value="editor">{text($locale,'Редактор — тарау қосады және тексеруге жібереді','Редактор — добавляет главы и отправляет на проверку')}</option></select></label><button class="button primary" disabled={busy||!user.verified}>{text($locale,'Шақыру жіберу','Отправить приглашение')}</button></form></details>
  </details>{/if}
 </section>{:else if !form&&!error}<p>{text($locale,'Әлі командаға қосылмадың. Жаңа командаға өтінім бер немесе иесінен поштаға шақыру сұра.','Ты пока не в команде. Подай заявку на новую или попроси владельца пригласить тебя по почте.')}</p>{/if}
 {/if}
{/if}
<style>
 .team-select{display:grid;gap:8px;max-width:420px;margin:0 0 20px;font-size:13px}.solo-tip{margin-bottom:20px}.solo-tip p{margin:4px 0 0}.team-form{max-width:1000px;border:1px solid var(--line);border-radius:12px;background:var(--panel);padding:24px;margin-bottom:24px}.form-heading,.team-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}.team-identity{display:flex;align-items:center;gap:16px;min-width:0}.team-identity>div{min-width:0}.team-identity .muted{margin:6px 0 0}h2{font-size:21px;line-height:1.35;margin:0;overflow-wrap:anywhere}h3{font-size:15px;margin:0}form{display:grid;gap:14px;margin-top:16px;max-width:640px}form .button{justify-self:start}label{display:grid;gap:8px;font-size:13px;min-width:0}.muted,small{font-size:13px;color:var(--muted)}.team{max-width:1000px;padding:24px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}.description{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6;font-size:14px;margin:20px 0 0;max-width:760px}.team-contact{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:13px;margin:8px 0 0}.team-contact>span{color:var(--muted)}.team-contact a{display:inline-flex;align-items:center;min-height:44px;overflow-wrap:anywhere;max-width:100%}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px}.actions .button{font-size:13px}.review-note{border-left:2px solid var(--line);padding:12px 16px;margin:20px 0}.review-note h3{margin-bottom:8px}.review-note p{line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}summary{display:flex;align-items:center;gap:10px;min-height:48px;cursor:pointer;font-size:14px;font-weight:550}summary::after{content:'+';margin-left:auto;color:var(--muted)}details[open]>summary::after{content:'−'}.avatar-settings{border-top:1px solid var(--line);margin-top:24px;padding-top:6px}.management{border-top:1px solid var(--line);margin-top:12px;padding-top:6px}.count{display:inline-flex;padding:3px 7px;border-radius:5px;background:var(--raised);color:var(--muted);font-size:11px;font-weight:500}.member-list,.invitation-list{max-height:360px;overflow:auto;overscroll-behavior:contain}.member-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);min-width:0}.member-row>div{min-width:0;overflow-wrap:anywhere}.member-row strong{font-size:13px;font-weight:550}.member-row .button{font-size:12px}.member-row .actions{margin:0}.invitations{margin-top:12px;border-top:1px solid var(--line);padding-top:6px}.invitations>.button{font-size:12px;margin:8px 0}.invitation-list>p{font-size:13px;margin:12px 0}.invite-composer{margin-top:12px;border-top:1px solid var(--line);padding-top:6px}.invite-composer>summary{color:var(--accent)}small{display:block;margin-top:4px}@media(max-width:480px){.team,.team-form{padding:16px}.team-identity{gap:12px}.team-identity h2{font-size:18px}.team-heading{align-items:start}.member-row{align-items:start;flex-wrap:wrap}.actions .button{flex:1 1 140px;text-align:center;justify-content:center}.team-contact{display:grid;gap:0}.member-list,.invitation-list{max-height:50dvh}}
</style>
